const fail = (status, m, codigo) => [{ json: { ok: false, status, body: { sucesso: false, erro: m, message: m, ...(codigo ? { codigo } : {}) } } }];
const falta = ["ERPNEXT_DOMAIN", "ERPNEXT_API_KEY", "ERPNEXT_API_SECRET"].filter(k => !$env[k]);
if (falta.length) return fail(500, 'PENDENTE_CONFIGURACAO_RITMO: variáveis ausentes no ambiente do Harmonia: ' + falta.join(', '), 'PENDENTE_CONFIGURACAO_RITMO');

const b = $input.first().json.body || {};
const order_nsu = String(b.order_nsu || '').trim();
if (!/^[A-Za-z0-9._-]{1,100}$/.test(order_nsu)) return fail(400, 'order_nsu ausente ou inválido');
const extra = {};
const tn = String(b.transaction_nsu || '').trim(); if (tn) extra.transaction_nsu = tn;
const sl = String(b.slug || b.invoice_slug || '').trim(); if (sl) extra.slug = sl;
return [{ json: { ok: true, order_nsu, extra } }];

const c = $input.first().json.data || {};
const bad = (m) => [{ json: { ok: false, status: 424, body: { sucesso: false, erro: m, message: m, codigo: 'PENDENTE_CONFIGURACAO_INFINITEPAY' } } }];
if (c.status !== 'conectado') return bad('PENDENTE_CONFIGURACAO_INFINITEPAY: conta InfinitePay não está conectada (status: ' + (c.status || 'desconhecido') + ')');
let meta = {}; try { meta = JSON.parse(c.metadados || '{}'); } catch (e) {}
const handle = String(meta.handle || meta.infinite_tag || c.conta_conectada || '').trim().replace(/^[$@]/, '');
if (!/^[A-Za-z0-9._-]{2,64}$/.test(handle)) return bad('PENDENTE_CONFIGURACAO_INFINITEPAY: InfiniteTag (handle) não identificada na credencial (metadados.handle ou conta_conectada)');

const e = $('Valida entrada').first().json;
return [{ json: { ok: true, payload: Object.assign({ handle, order_nsu: e.order_nsu }, e.extra) } }];

const j = $input.first().json;
const orderNsu = $('Valida entrada').first().json.order_nsu;
const ok = (status, body) => [{ json: { status, body: Object.assign({ order_nsu: orderNsu }, body) } }];
const st = String(j.status || j.payment_status || '').toLowerCase();
if (j.success === true && j.paid === true) return ok(200, { status: 'pago', valor_pago: j.paid_amount ?? null, metodo: j.capture_method ?? null, parcelas: j.installments ?? null });
if (['refused', 'declined', 'denied', 'failed', 'canceled', 'cancelled', 'recusado', 'recusada', 'negado'].includes(st)) return ok(200, { status: 'recusado' });
if (j.paid === false) return ok(200, { status: 'pendente' });
// Qualquer outra coisa: NÃO é pago, NÃO é pendente confirmado, e NÃO autoriza nova cobrança. Fica em reconciliação.
return ok(200, { status: 'indeterminado', reconciliar: true });

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
if (upstream === 404) { const m = "PENDENTE_CONFIGURACAO_INFINITEPAY: credencial 'infinitepay' n\u00e3o encontrada no Ritmo (Synapse Credencial Externa)"; return [{ json: { status: 424, body: { sucesso: false, erro: m, message: m, codigo: "PENDENTE_CONFIGURACAO_INFINITEPAY" } } }]; }
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao ler a credencial InfinitePay no Ritmo" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "ritmo" } } }];

const it = $input.first().json || {};
const e = it.error || it;
const raw = String(e.description || e.message || 'erro desconhecido');
const upstream = Number(e.httpCode || e.statusCode || e.status || (e.cause && e.cause.status) || 0);
const clean = raw.replace(/https?:\/\/\S+/g, '[url]').replace(/(token|api_access_token|authorization)\S*/gi, '[omitido]').slice(0, 300);
const status = upstream === 404 ? 404 : 502;
const m = "Falha ao consultar o pagamento na InfinitePay" + (upstream ? ' (HTTP ' + upstream + ')' : '') + (true ? ': ' + clean : '');
return [{ json: { status, body: { sucesso: false, erro: m, message: m, origem: "infinitepay" } } }];
